#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <unistd.h>

/* Async crypto commitment scheme with worker threads */

typedef struct {
    uint8_t nonce[32];
    uint8_t commitment[32];
    uint8_t blinding[32];  /* Additional blinding factor */
    int phase;  /* 0=init, 1=committed, 2=revealed */
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int ready;
} crypto_session_t;

typedef struct {
    crypto_session_t *session;
    uint8_t *secret;
    size_t secret_len;
    int result;
} async_task_t;

/* Simplified HMAC-like commitment: H(nonce || blinding || secret) */
static void compute_commitment(const uint8_t *nonce, const uint8_t *blinding,
                               const uint8_t *secret, size_t secret_len,
                               uint8_t *out) {
    /* Simplified hash for demonstration - XOR-fold with rotation */
    uint8_t state[32];
    memset(state, 0x36, 32);
    for (size_t i = 0; i < 32; i++)
        state[i] ^= nonce[i];
    for (size_t i = 0; i < 32; i++)
        state[i] ^= blinding[i];
    for (size_t i = 0; i < secret_len; i++)
        state[i % 32] ^= secret[i] ^ (uint8_t)(i * 0x9e);
    /* Second pass with different constant */
    for (size_t i = 0; i < 32; i++)
        state[i] = (state[i] << 3) | (state[i] >> 5);
    memcpy(out, state, 32);
}

/* Returns 0 on success, -1 on failure. Ensures the full buffer is filled
 * with random data; callers must check the return value. */
static int generate_nonce(uint8_t *buf, size_t len) {
    FILE *f = fopen("/dev/urandom", "r");
    if (!f)
        return -1;

    size_t total = 0;
    while (total < len) {
        size_t r = fread(buf + total, 1, len - total, f);
        if (r == 0) {
            /* Short read / error - do not leave buffer partially filled */
            fclose(f);
            return -1;
        }
        total += r;
    }
    fclose(f);
    return 0;
}

/* Phase 1: Commit - generates nonce, blinding, and computes commitment */
static void *commit_worker(void *arg) {
    async_task_t *task = (async_task_t *)arg;
    crypto_session_t *sess = task->session;

    pthread_mutex_lock(&sess->lock);

    if (generate_nonce(sess->nonce, 32) != 0 ||
        generate_nonce(sess->blinding, 32) != 0) {
        /* Failed to obtain secure randomness - abort commit */
        task->result = -1;
        pthread_mutex_unlock(&sess->lock);
        return NULL;
    }
    compute_commitment(sess->nonce, sess->blinding, task->secret,
                       task->secret_len, sess->commitment);
    sess->phase = 1;
    sess->ready = 1;

    pthread_cond_signal(&sess->cond);
    pthread_mutex_unlock(&sess->lock);

    task->result = 0;
    return NULL;
}

/* Phase 2: Verify - checks if revealed secret matches commitment.
 * Requires both the secret AND the blinding factor for verification. */
static int verify_reveal(crypto_session_t *sess, const uint8_t *claimed_secret,
                         size_t claimed_len, const uint8_t *claimed_blinding) {
    uint8_t recomputed[32];

    pthread_mutex_lock(&sess->lock);
    while (!sess->ready)
        pthread_cond_wait(&sess->cond, &sess->lock);

    if (sess->phase != 1) {
        pthread_mutex_unlock(&sess->lock);
        return -1;
    }

    compute_commitment(sess->nonce, claimed_blinding, claimed_secret,
                       claimed_len, recomputed);

    /* Timing-independent comparison under lock */
    int diff = 0;
    for (int i = 0; i < 32; i++)
        diff |= recomputed[i] ^ sess->commitment[i];

    /* Only transition phase after successful verification */
    if (diff == 0)
        sess->phase = 2;

    pthread_mutex_unlock(&sess->lock);

    return (diff == 0) ? 0 : -1;
}

/* Nonce is public in commitment schemes - but blinding is NOT exposed.
 * Even if an observer reads the nonce, they cannot forge a commitment
 * without knowing the secret blinding factor. */
static int read_session_nonce(crypto_session_t *sess, uint8_t *out_nonce) {
    pthread_mutex_lock(&sess->lock);
    if (sess->phase >= 1) {
        memcpy(out_nonce, sess->nonce, 32);
        pthread_mutex_unlock(&sess->lock);
        return 0;
    }
    pthread_mutex_unlock(&sess->lock);
    return -1;
}

/* Async await pattern: submit commitment and get future */
typedef struct {
    pthread_t thread;
    async_task_t task;
} crypto_future_t;

static crypto_future_t *async_commit(crypto_session_t *sess,
                                     uint8_t *secret, size_t secret_len) {
    crypto_future_t *fut = calloc(1, sizeof(crypto_future_t));
    if (!fut) return NULL;

    fut->task.session = sess;
    fut->task.secret = secret;
    fut->task.secret_len = secret_len;

    if (pthread_create(&fut->thread, NULL, commit_worker, &fut->task) != 0) {
        free(fut);
        return NULL;
    }
    return fut;
}

static int await_commit(crypto_future_t *fut) {
    pthread_join(fut->thread, NULL);
    int res = fut->task.result;
    free(fut);
    return res;
}

static crypto_session_t *create_session(void) {
    crypto_session_t *sess = calloc(1, sizeof(crypto_session_t));
    if (!sess) return NULL;
    pthread_mutex_init(&sess->lock, NULL);
    pthread_cond_init(&sess->cond, NULL);
    sess->phase = 0;
    sess->ready = 0;
    return sess;
}

static void destroy_session(crypto_session_t *sess) {
    /* Securely wipe sensitive material */
    volatile uint8_t *p = (volatile uint8_t *)sess->blinding;
    for (size_t i = 0; i < 32; i++) p[i] = 0;
    p = (volatile uint8_t *)sess->nonce;
    for (size_t i = 0; i < 32; i++) p[i] = 0;
    pthread_mutex_destroy(&sess->lock);
    pthread_cond_destroy(&sess->cond);
    free(sess);
}

/* Example usage demonstrating the protocol */
int main(void) {
    crypto_session_t *sess = create_session();
    uint8_t secret[] = "my_secret_bid_value_42";

    /* Async commit phase */
    crypto_future_t *fut = async_commit(sess, secret, sizeof(secret) - 1);
    if (!fut || await_commit(fut) != 0) {
        fprintf(stderr, "Commit failed\n");
        destroy_session(sess);
        return 1;
    }

    /* Even if attacker reads nonce, they cannot forge without blinding */
    uint8_t stolen_nonce[32];
    if (read_session_nonce(sess, stolen_nonce) == 0) {
        /* Attacker has nonce but NOT blinding - cannot compute valid commitment */
        uint8_t fake_commitment[32];
        uint8_t attacker_secret[] = "attacker_wins_43";
        uint8_t fake_blinding[32];
        memset(fake_blinding, 0xAA, 32); /* Wrong blinding */
        compute_commitment(stolen_nonce, fake_blinding, attacker_secret,
                          sizeof(attacker_secret) - 1, fake_commitment);
        /* This will NOT match sess->commitment */
    }

    /* Legitimate reveal - requires the blinding factor stored privately */
    uint8_t correct_blinding[32];
    pthread_mutex_lock(&sess->lock);
    memcpy(correct_blinding, sess->blinding, 32);
    pthread_mutex_unlock(&sess->lock);

    int result = verify_reveal(sess, secret, sizeof(secret) - 1, correct_blinding);
    printf("Verification: %s\n", result == 0 ? "OK" : "FAILED");

    /* Wipe local copy of blinding */
    volatile uint8_t *bp = (volatile uint8_t *)correct_blinding;
    for (size_t i = 0; i < 32; i++) bp[i] = 0;

    destroy_session(sess);
    return 0;
}
